// translate resolves key for locale; an unknown locale falls back to en and
// an unknown key to the key itself.
func translate(locale i18n.Locale, key string) string {
	l, ok := labels[key]
	if !ok {
		return key
	}
	for i, loc := range labelLocales {
		if loc == locale && l[i] != "" {
			return l[i]
		}
	}
	return l[1]
}
